/* ---------- Una persona, muchos roles ---------- */
{id:"master_it",kind:"test",film:1,chapter:"entities",c:"#26a060",name:"¿Dato maestro o no?",vis:"test",vh:640,
  alt:"Una cosa de una industria, en una tarjeta de su color, junto a las cuatro preguntas y tus respuestas.",
  idea:"Cuatro preguntas dicen qué cosas hay que gestionar como datos maestros: una cosa, no un evento; usada por más de un proceso; guardada en más de un lugar; y que importe cuando las copias no coinciden.",
  points:["Algo de lo que trata el negocio, no algo que pasa.","Lo usa más de un proceso.","Se crea o se cambia en más de un lugar, así que las copias pueden no coincidir.","Importa cuando no coinciden: dinero, seguridad, la ley o la confianza de alguien."],
  real:"Cuatro síes son un argumento fuerte, no una ley. Algo puede pasar las cuatro y aun así esperar, porque se puede hacer de un sistema el único lugar donde se crea. Otra cosa puede no pasar una y gestionarse como dato maestro de todos modos, porque una copia equivocada cuesta demasiado. Haz las preguntas junto con quienes usan los datos: saben dónde no coinciden las copias.",
  w:{prompt:"Elige una cosa, responde las cuatro preguntas sobre ella y luego comprueba.",label:"Cosa",yes:"Sí",no:"No",
    qs:["¿Una cosa, no un evento?","¿Lo usa más de un proceso?","¿Se guarda en más de un lugar?","¿Importa si las copias no coinciden?"],
    kindOf:{uni:"Universidad",health:"Salud",bank:"Banca",energy:"Energía",retail:"Comercio"},
    verdicts:{master:"Dato maestro",txn:"Una transacción",not:"Todavía no"},
    items:[{t:"Un proveedor",ind:"retail",a:[1,1,1,1],verdict:"master",say:"Cuatro síes: un solo proveedor, cotejado y guardado una vez, que leen tanto compras como pagos.",
        why:["Los proveedores son cosas de las que trata la tienda.","Compras, pagos y devoluciones: todos los usan.","Compras y cuentas por pagar tienen cada una su propia copia.","Una cuenta bancaria equivocada le paga a la empresa equivocada."]},
      {t:"Un pago",ind:"bank",a:[0,null,null,null],verdict:"txn",say:"Sucede: regístralo una vez, haz que apunte al cliente, y no lo gestiones como dato maestro.",
        why:["Sucede una vez, en una fecha: una transacción.","Da igual la respuesta: ya no pasó la primera pregunta.","Da igual la respuesta: ya no pasó la primera pregunta.","Da igual la respuesta: ya no pasó la primera pregunta."]},
      {t:"Una sala de hospital",ind:"health",a:[1,1,1,1],verdict:"master",say:"Cuatro síes: una sola lista de salas, cada una con sus camas y su especialidad, que leen todos los sistemas.",
        why:["Una sala es un lugar del que trata el hospital.","Admisión, turnos y la farmacia: todos la usan.","El sistema de camas, la app de turnos y el sistema de la farmacia la escriben cada uno a su manera.","Los medicamentos pueden ir al lugar equivocado."]},
      {t:"Una materia",ind:"uni",a:[1,1,1,1],verdict:"master",say:"Cuatro síes: las materias son datos maestros, guardadas una vez, con sus propios códigos y responsables.",
        why:["Una materia es algo que la universidad enseña.","La matrícula, los horarios y la plataforma de aprendizaje: todos la usan.","El sistema del plan de estudios, el de horarios y la plataforma de aprendizaje guardan cada uno una copia.","Una materia equivocada significa una matrícula equivocada, o créditos que no cuentan."]},
      {t:"Una reserva de aula",ind:"uni",a:[0,null,null,null],verdict:"txn",say:"Sucede, en una fecha: una transacción que apunta a un aula, que es un dato maestro.",
        why:["Una reserva sucede: alguien, un aula, una hora.","Da igual la respuesta: ya no pasó la primera pregunta.","Da igual la respuesta: ya no pasó la primera pregunta.","Da igual la respuesta: ya no pasó la primera pregunta."]},
      {t:"La lista de correo de un club deportivo",ind:"uni",a:[1,0,0,0],verdict:"not",say:"Todavía no: un proceso, una copia, nada que conciliar. Gestiónala como dato maestro el día en que un segundo sistema empiece a guardarla.",
        why:["La lista es una cosa, que se mantiene en el tiempo.","Solo la usa el boletín del club.","Solo el club la guarda.","Con una sola copia, no hay desacuerdo posible."]}],
    sayAsk:"{n} de {of} preguntas respondidas.",sayDone:"{n} de {of} cosas comprobadas. Elige otra."}}
